    c1 = CH.indexOf(b64.charAt(i + 1));
    c2 = b64.charAt(i + 2) === '=' ? -1 : CH.indexOf(b64.charAt(i + 2));
    c3 = b64.charAt(i + 3) === '=' ? -1 : CH.indexOf(b64.charAt(i + 3));
