if (!art) {
var divs = doc.select('div, td');
var best = null, bs = -1;
for (var i = 0; i < divs.size(); i++) {
var el = divs.get(i);
var t = String(el.text());
var sc = t.length - el.select('a').size() * 60;
if (sc > bs) { bs = sc; best = el; }
}
art = best;
}
if (!art) return '';
art.select('script, style, ins, iframe, #content_tip').remove();
var h = String(art.html());
h = h.replace(/（本章未完，请点击下一页继续阅读）/g, '');
h = h.replace(/最新网址：m\.ciweiku\.com/g, '');
h = h.replace(/^\s*(<br\s*\/?>\s*)*[^<]{0,80}?\(第\d+\/\d+页\)/, '');
h = h.replace(/^(\s|<br\s*\/?>)+/, '');
try {
var cn = String(chapter.name || '').replace(/\s+/g, ' ').trim();
if (cn) {
var segEnd = h.indexOf('<br');
var seg = (segEnd >= 0 ? h.substring(0, segEnd) : h).replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
if (seg === cn) {
var rest = segEnd >= 0 ? h.substring(segEnd) : '';
h = rest.replace(/^(\s|<br\s*\/?>)+/, '');
}
